function spaceView() { return titleBlock('UMA VISÃO DO TODO', 'Meu espaço', 'Organize por áreas da vida. Mantenha por perto o que faz sentido para você.', btn(spaceTab === 'areas' ? 'Nova área' : spaceTab === 'projects' ? 'Novo projeto' : 'Nova página', spaceTab === 'areas' ? 'new-area' : spaceTab === 'projects' ? 'new-project' : 'new-page', 'primary', 'plus')) + `<div class="space-topline">${tabs([['areas', 'Áreas', state.areas.length], ['projects', 'Projetos', state.projects.length], ['pages', 'Páginas', state.pages.length]], spaceTab, 'space-tab')}<button class="text-button" data-action="nav" data-view="inbox">${icon('inbox')} Caixa de entrada <span class="count">${state.tasks.filter(t => !t.done && !t.date && !t.projectId && !t.areaId).length}</span></button></div>` + (spaceTab === 'areas' ? `<div class="area-grid">${state.areas.map(areaCard).join('') || `<div class="area-onboarding"><span class="empty-icon">${icon('folder')}</span><h2>As partes da vida, no seu lugar.</h2><p>Comece por uma área. Você pode adicionar outras quando precisar.</p><div class="area-suggestions">${[['Rotina', 'blue'], ['Trabalho', 'orange'], ['Estudos', 'purple'], ['Treinos', 'green'], ['Metas', 'rose'], ['Financeiro', 'green'], ['Viagens', 'blue']].map(([title, color]) => `<button class="button secondary" data-action="suggest-area" data-title="${title}" data-color="${color}"><i class="color-dot ${color}"></i>${title}</button>`).join('')}</div>${btn('Criar outra área', 'new-area', 'secondary', 'plus')}</div>`}</div>` : spaceTab === 'projects' ? `<div class="project-grid">${state.projects.filter(p => !p.archived).map(projectCard).join('') || empty('Seus projetos ficam aqui.', 'Crie um projeto e, se quiser, escolha uma área.', 'new-project', 'Novo projeto')}</div>${state.projects.some(p => p.archived) ? '<h2 class="project-heading">Arquivados</h2><div class="project-grid">' + state.projects.filter(p => p.archived).map(projectCard).join('') + '</div>' : ''}` : `<div class="page-template-banner"><div>${icon('book')}<span><strong>Um roteiro para organizar a semana.</strong><small>Comece com um modelo ou uma página em branco.</small></span></div>${btn('Usar roteiro semanal', 'template-page')}</div><div class="pages-grid">${state.pages.map(pageCard).join('') || empty('Um espaço para suas ideias.', 'Textos, títulos e checklists, do seu jeito.', 'new-page', 'Nova página')}</div>`) }
function areaView() { const a = area(route.id); if (!a) return empty('Área não encontrada.', 'Abra Meu espaço para escolher outra área.', 'nav-space', 'Meu espaço'); const tasks = state.tasks.filter(t => effectiveArea(t) === a.id), projects = state.projects.filter(p => p.areaId === a.id && !p.archived), pages = state.pages.filter(p => effectiveArea(p) === a.id); return titleBlock('ÁREA DA VIDA', a.title, esc(a.description || 'O que você precisa fazer e guardar nesta área, em um só lugar.'), `<button class="button secondary" data-action="edit-area" data-id="${esc(a.id)}">Editar área</button>${btn(areaTab === 'tasks' ? 'Nova tarefa' : areaTab === 'projects' ? 'Novo projeto' : 'Nova página', areaTab === 'tasks' ? 'new-task' : areaTab === 'projects' ? 'new-project' : 'new-page', 'primary', 'plus')}`) + tabs([['tasks', 'Tarefas', tasks.filter(t => !t.done).length], ['projects', 'Projetos', projects.length], ['pages', 'Páginas', pages.length]], areaTab, 'area-tab') + (areaTab === 'tasks' ? taskSection(tasks) : areaTab === 'projects' ? `<div class="project-grid">${projects.map(projectCard).join('') || empty('Nenhum projeto nesta área.', 'Reúna aqui os projetos relacionados a ' + esc(a.title) + '.', 'new-project', 'Novo projeto')}</div>` : `<div class="pages-grid">${pages.map(pageCard).join('') || empty('Espaço para guardar ideias.', 'Crie uma página para esta área.', 'new-page', 'Nova página')}</div>`) }
const originalRender = render;
render = function () { if (route.view === 'space' || route.view === 'area') { renderNav(); $('#breadcrumb').textContent = route.view === 'space' ? 'Meu espaço' : area(route.id)?.title || 'Área'; document.title = $('#breadcrumb').textContent + ' · clarity.ai'; $('#view').className = 'view ' + route.view; $('#view').innerHTML = route.view === 'space' ? spaceView() : areaView(); icons() } else originalRender() };
const originalTaskRow = taskRow;
function taskBadges(t) { const subtasks = t.subtasks || []; return `${subtasks.length ? `<span class="subtask-count" title="Subtarefas concluídas">${icon('check')}${subtasks.filter(s => s.done).length}/${subtasks.length}</span>` : ''}${t.repeat && t.repeat !== 'none' ? `<span class="repeat-badge" title="${repeatNames[t.repeat]}">↻</span>` : ''}` }
