const originalDelete = $('#entity-delete').onclick;
$('#entity-delete').onclick = () => {
    if (editing.kind !== 'area') { originalDelete(); return }
    const id = editing.id, index = state.areas.findIndex(a => a.id === id); if (index < 0) return; const removed = state.areas.splice(index, 1)[0], linked = [];
    for (const list of [state.tasks, state.projects, state.pages]) for (const entity of list) if (entity.areaId === id) { linked.push(entity); entity.areaId = '' }
    $('#entity-dialog').close(); if (route.view === 'area' && route.id === id) navigate('space'); commit('Área excluída. Tarefas, projetos e páginas foram preservados.', () => { state.areas.splice(index, 0, removed); linked.forEach(x => x.areaId = id); commit('Área restaurada.') });
};
document.addEventListener('click', e => { const b = e.target.closest('[data-action]'); if (!b) return; switch (b.dataset.action) { case 'new-area': openEntity('area'); break; case 'edit-area': openEntity('area', area(b.dataset.id)); break; case 'suggest-area': openEntity('area', null, { title: b.dataset.title, color: b.dataset.color }); break; case 'space-tab': spaceTab = b.dataset.tab; render(); break; case 'area-tab': areaTab = b.dataset.tab; render(); break; case 'nav-space': navigate('space'); break; case 'add-subtask': addFormSubtask(); break; case 'remove-subtask': formSubtasks = formSubtasks.filter(s => s.id !== b.dataset.id); renderSubtasks(); break } });
const originalCommandResults = commandResults;
commandResults = function () { originalCommandResults(); const q = $('#command-input').value.trim().toLocaleLowerCase('pt-BR'), matches = state.areas.filter(a => (a.title + ' ' + a.description).toLocaleLowerCase('pt-BR').includes(q)); if (matches.length) $('#command-results .command-empty')?.remove(); $('#command-results').insertAdjacentHTML('beforeend', (!q ? `<button data-command-new="area">${icon('folder')}<span>Nova área</span>${icon('plus')}</button>` : '') + (matches.length ? '<div class="command-group">ÁREAS DA VIDA</div>' + matches.map(a => `<button data-command-view="area" data-id="${esc(a.id)}">${icon('folder')}<span>${esc(a.title)}</span><small>Área</small></button>`).join('') : '')) };
